<span class="line"><span style="color:#E5C07B;">        context</span><span style="color:#ABB2BF;">.</span><span style="color:#E5C07B;">Items</span><span style="color:#ABB2BF;">[</span><span style="color:#98C379;">&quot;User&quot;</span><span style="color:#ABB2BF;">] </span><span style="color:#56B6C2;">=</span><span style="color:#E06C75;"> user</span><span style="color:#ABB2BF;">;</span></span>
